SELECT DISTINCT po.id, po.supplier_name, po.supplier_phone, po.unit_price, po.total_amount, po.purchase_date, po.expected_arrival_date, po.status, po.remark, po.is_deleted, po.created_by, po.created_at, po.updated_at FROM t_purchase_order po LEFT JOIN t_purchase_order_item poi ON po.id = poi.purchase_order_id LEFT JOIN t_purchase_request pr ON poi.purchase_request_id = pr.id WHERE po.is_deleted = 0
AND pr.project_id = #{projectId}
AND po.status = #{status}
ORDER BY po.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT po.id) FROM t_purchase_order po LEFT JOIN t_purchase_order_item poi ON po.id = poi.purchase_order_id LEFT JOIN t_purchase_request pr ON poi.purchase_request_id = pr.id WHERE po.is_deleted = 0
AND pr.project_id = #{projectId}
AND po.status = #{status}
